import{z as B,x as A,o,c as p,q as s,j as l,D as r,d as t,s as E,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const W=JSON.parse('{"title":"Quorum 读写","description":"","frontmatter":{"title":"Quorum 读写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quorum-rw.md","filePath":"cs/quorum-rw.md","lastUpdated":1791063341000}'),d={name:"cs/quorum-rw.md"};function u(m,a,D,C,c,f){const n=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="quorum-读写" tabindex="-1">Quorum 读写 <a class="header-anchor" href="#quorum-读写" aria-label="Permalink to &quot;Quorum 读写&quot;">​</a></h1><div class="epigraph"><p>写集与读集必须相交。相交点上带着足够新的时间戳，读就能拼出最近一次完成的写。</p><footer>—— 据 Gifford, Weighted Voting for Replicated Data, SOSP 1979；Attiya, Bar-Noy and Dolev, Sharing Memory Robustly in Message-Passing Systems, JACM 1995 整理</footer></div><p>上一课<a href="/cs/chain-replication">链式复制</a>用拓扑固定提交点。缺口是<strong>集合相交</strong>：不排成链，也能让每次读撞上每次写。本课钉 \\(R+W\\gt n\\)（及权重推广），不把 Dynamo 的 sloppy quorum 提前当默认。后课反熵处理「写没到齐」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个副本，写等 \\(W\\) 个 ack，读问 \\(R\\) 个，取时间戳最大者。若 \\(R+W\\gt n\\)，任一读集与任一写集共享至少一节点，该节点若保存了那次写，读就能看见。Attiya–Bar-Noy–Dolev（ABD）在异步崩溃下用两轮读/写给出线性一致寄存器：读也要再传播，防止旧值回写。</p><p>缺口：相交是安全的组合学；延迟是等最慢的那个法定人数成员。\\(W=n,R=1\\) 写最慢读最快；\\(W=1,R=n\\) 相反；\\(W=R=\\lfloor n/2\\rfloor+1\\) 对称。这是<a href="/cs/cap-pacelc">PACELC</a>无分区时的旋钮。</p><p><span class="marginnote">Gifford 加权投票：节点带票数，法定人数是票和，不是台数。ABD 说明消息传递上模拟共享内存要两轮。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每值带单调时间戳（Lamport 钟或主序）。写：把新值送到 \\(W\\) 个。读：收 \\(R\\) 份，选最大时间戳；若要线性一致，把该值再写回 \\(W\\)（ABD 的 read-repair/传播）。时间戳不可比时不能只靠墙钟——接<a href="/cs/clock-drift">物理时钟</a>的 \\(\\varepsilon\\)。</p>',9)),(o(),l(i,null,{default:r(()=>[E(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WSET%5B%22%E5%86%99%E9%9B%86%20%7CW%7C%22%5D%20--%3E%20INT%5B%22%E9%9D%9E%E7%A9%BA%E7%9B%B8%E4%BA%A4%22%5D%0A%20%20RSET%5B%22%E8%AF%BB%E9%9B%86%20%7CR%7C%22%5D%20--%3E%20INT%0A%20%20INT%20--%3E%20TS%5B%22%E6%9C%80%E5%A4%A7%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%0A%20%20TS%20--%3E%20VAL%5B%22%E8%AF%BB%E5%80%BC%20%2F%20%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"分区：多数派只在一侧，另一侧 \\(W\\) 凑不齐则停写（CP）。若降低 \\(W\\) 使 \\(R+W\\le n\\)，相交消失，进入最终一致。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"Sloppy quorum（后课 Dynamo）：写进提示节点，相交暂时不成立，靠反熵补。那是故意放弃 ABD 安全换可用。严格 quorum 下，失败的写可能只到 \\(W-1\\)：读可能看见也可能看不见，线性一致要求把不确定的写当成未提交或用两阶段。工程上常用「写满 W 才 ack 客户端」，未 ack 的写以重试+幂等消化。",-1)),(o(),l(i,null,{default:r(()=>[E(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%225%20%E4%B8%AA%E5%89%AF%E6%9C%AC%22%5D%20--%3E%20W2%7B%22%E5%8F%82%E6%95%B0%E6%80%8E%E4%B9%88%E9%85%8D%3F%22%7D%0A%20%20W2%20--%3E%7C%22W%3D5%2C%20R%3D1%22%7C%20C1%5B%22%E8%AF%BB%E6%9C%80%E5%BF%AB%2C%20%E5%86%99%E8%A6%81%E7%AD%89%E5%85%A8%E9%83%A8%22%5D%0A%20%20W2%20--%3E%7C%22W%3D1%2C%20R%3D5%22%7C%20C2%5B%22%E5%86%99%E6%9C%80%E5%BF%AB%2C%20%E8%AF%BB%E8%A6%81%E7%AD%89%E5%85%A8%E9%83%A8%22%5D%0A%20%20W2%20--%3E%7C%22W%3D3%2C%20R%3D3%22%7C%20C3%5B%22%E4%B8%A4%E4%BE%A7%E5%AF%B9%E7%A7%B0%2C%20%E9%83%BD%E8%A6%81%E8%BF%87%E5%8D%8A%22%5D%0A%20%20C1%20--%3E%20I%5B%22R%2BW%3D6%20%3E%205%2C%20%E7%9B%B8%E4%BA%A4%E6%88%90%E7%AB%8B%22%5D%0A%20%20C2%20--%3E%20I%0A%20%20C3%20--%3E%20I%0A%20%20I%20--%3E%20OK%5B%22%E4%BB%BB%E4%B8%80%E8%AF%BB%E5%BF%85%E6%92%9E%E4%B8%8A%E6%9C%80%E8%BF%91%E5%86%99%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：\\(n=5\\)、\\(W=3\\)、\\(R=3\\) 时，写集占 3 个节点、读集也占 3 个，5 个位置装不下两组互不相交的 3 元集——鸽笼原理保证至少重合 1 个。若把 \\(W\\) 降到 2，则 \\(2+3\\le 5\\)，读集恰好落在没收到写的那两个节点上时，就会读到旧值。</span></p><p><span class="marginnote">直觉类比：可以把它想象成往 5 个柜子里同时塞留言，写操作只要塞进 3 个柜子就算完成；读操作随机打开 3 个柜子找最新留言。因为「3+3 比 5 多」，打开的柜子里必定有一个见过最新那条留言。</span></p><p><span class="marginnote">常见误区：凑齐多数派写才 ack，不代表每个写都一定成功——3 个里挂 1 个，写就停在 2 份，读可能看见也可能看不见。线性一致的正确处理是把它当未提交，靠重试与幂等消化，而不是当作「最终会到齐」。</span></p><p>权重：慢盘少投票，SSD 多投票，仍要最坏相交。不要把权重当成负载均衡的充分条件。</p><p>本课不把 Raft 多数派日志当寄存器 quorum：共识是对<strong>操作序列</strong>的相交，寄存器是对<strong>单值</strong>的相交。后课 RSM 会接上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Merkle 树，不引入 LWW 细节。不把「三个九」当 \\(n=3\\) 的证明。后课默认：\\(R+W\\gt n\\) 加单调时间戳给崩溃异步寄存器；要可用性就放松相交并接受冲突。Dynamo 把放松做成系统。</p><p>相交是集合论，时间戳是打破平局的全序。缺一则读无「最近」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(R+W\\gt n\\)（或加权票和）保证读写集相交。</li><li>ABD：异步线性一致寄存器要读传播。</li><li>相交放松即放弃该寄存器的线性一致。</li><li>出处：Gifford, SOSP 1979；Attiya, Bar-Noy and Dolev, JACM 1995。</li></ul>',10))])}const g=B(d,[["render",u]]);export{W as __pageData,g as default};
